n=22; bg=4
grid=[[bg]*n for _ in range(n)]
objs=[(0,0,8,2),(0,17,2,9),(5,0,8,3),(8,12,2,6),(12,17,2,7),(14,0,8,9)]
for r,c,b,i in objs:
    for dr in range(5):
        for dc in range(5):
            grid[r+dr][c+dc] = i if 1<=dr<=3 and 1<=dc<=3 else b
print(json.dumps(grid))

